class TTLCache:
    def __init__(self, ttl, clock):
        self.ttl = ttl
        self.clock = clock
        self.store = {}
    def put(self, k, v):
        self.store[k] = (v, self.clock())
    def get(self, k):
        if k not in self.store:
            return None
        v, t = self.store[k]
        if self.clock() - t >= self.ttl:
            del self.store[k]
            return None
        return v

