import threading

balances = {"acct": 100}
lock = threading.Lock()

def withdraw(amount, use_lock):
    if use_lock:
        with lock:
            bal = balances["acct"]
            if bal >= amount:
                balances["acct"] = bal - amount
                return True
            return False
    else:
        bal = balances["acct"]
        if bal >= amount:
            balances["acct"] = bal - amount
            return True
        return False

# Force the interleaving deterministically with a barrier instead of hoping for it
results = []
barrier = threading.Barrier(2)
def racer():
    bal = balances["acct"]
    barrier.wait()  # both threads have now READ 100
    if bal >= 80:
        balances["acct"] = bal - 80
        results.append("withdrew")

balances["acct"] = 100
ts = [threading.Thread(target=racer) for _ in range(2)]
for t in ts: t.start()
for t in ts: t.join()
