def parse_all(lines):
    out = []
    for ln in lines:
        try:
            out.append(int(ln))
        except ValueError:
            pass  # swallow: the bug-enabler
    return out

def parse_all_strict(lines):
    out, errors = [], []
    for ln in lines:
        try:
            out.append(int(ln))
        except ValueError:
            errors.append(ln)
    return out, errors

